                int ends=(int)natsEvents().stream().filter(e->e.kind.equals("SNAPSHOT_END")).count();kill();ClusterHarness.sql("mysql","INSERT INTO "+items+" (id,document) VALUES (4,NULL)");start();await(()->natsEvents().stream().anyMatch(e->e.kind.equals("ROW")&&e.change.after!=null&&"4".equals(e.change.after.get(0).value)));assertEquals(ends,natsEvents().stream().filter(e->e.kind.equals("SNAPSHOT_END")).count());
                Path marker=Paths.get(System.getenv("RIVOMESH_BROKER_RESTART_DIR"));
