                    Files.write(marker.resolve("restart."+round+".continue"),new byte[]{1});await(()->Files.exists(marker.resolve("restart."+restart+".done")),180);
                    await(()->natsEvents().stream().anyMatch(e->e.kind.equals("ROW")&&e.change.after!=null&&value.equals(e.change.after.get(0).value)));
                    await(()->ack(journal,"rabbit")==last(journal)&&ack(journal,"nats")==last(journal)&&ack(journal,"kafka")==last(journal)&&ack(journal,"postgres")==last(journal)&&ack(journal,"redis")==last(journal)&&ack(journal,"pulsar")==last(journal)&&ack(journal,"rocket")==last(journal)&&ack(journal,"artemis")==last(journal));
                    await(()->redisEvents().stream().anyMatch(e->e.kind.equals("ROW")&&e.change.after!=null&&value.equals(e.change.after.get(0).value)));await(()->pulsarEvents().stream().anyMatch(e->e.kind.equals("ROW")&&e.change.after!=null&&value.equals(e.change.after.get(0).value)));await(()->rocketEvents().stream().anyMatch(e->e.kind.equals("ROW")&&e.change.after!=null&&value.equals(e.change.after.get(0).value)));await(()->artemisEvents(false).stream().anyMatch(e->e.kind.equals("ROW")&&e.change.after!=null&&value.equals(e.change.after.get(0).value)));await(()->journal.subscriptions().stream().allMatch(sub->sub.errorCode==null));
